<?php
require_once __DIR__.'/includes/db.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$s=$pdo->prepare("SELECT * FROM products WHERE id=? AND status='published'");$s->execute([$id]);$p=$s->fetch();if(!$p){http_response_code(404);$pageTitle='Không tìm thấy';require __DIR__.'/includes/header.php';echo'<div class="empty-state"><h2>Không tìm thấy nội dung</h2><a href="index.php">Về trang chủ</a></div>';require __DIR__.'/includes/footer.php';exit;}$s=$pdo->prepare("SELECT * FROM screenshots WHERE product_id=? ORDER BY sort_order,id");$s->execute([$id]);$shots=$s->fetchAll();$pageTitle=$p['title'].' | HENDY';require __DIR__.'/includes/header.php';?><a class="back-link" href="index.php">← Quay lại danh sách</a><section class="detail-layout"><div class="detail-main"><div class="eyebrow"><?=e($p['category'])?></div><h1><?=e($p['title'])?></h1><div class="price-large"><?=e($p['price']?:'Liên hệ')?></div><div class="prose"><?=nl2br(e($p['description']))?></div><?php if($p['external_url']):?><a class="button primary" href="<?=e($p['external_url'])?>" target="_blank" rel="noopener noreferrer">Truy cập dịch vụ ↗</a><?php endif;?></div><aside class="detail-side"><div class="side-label">THÔNG TIN</div><p><strong>Danh mục</strong><br><?=e($p['category']?:'Dịch vụ')?></p><p><strong>Cập nhật</strong><br><?=e(date('d/m/Y',strtotime($p['updated_at'])))?></p></aside></section><?php if($shots):?><section class="screens-section"><div class="eyebrow">GALLERY</div><h2>Hình ảnh & giao diện</h2><div class="screens-grid"><?php foreach($shots as $s):?><a href="<?=e($s['image_path'])?>" target="_blank" rel="noopener"><img src="<?=e($s['image_path'])?>" alt="<?=e($s['caption'])?>" loading="lazy"><span><?=e($s['caption'])?></span></a><?php endforeach;?></div></section><?php endif;?><?php require __DIR__.'/includes/footer.php';?>